const fs=require('fs'),path=require('path'),crypto=require('crypto'),sharp=require('../../vendor/upscale/node_modules/sharp'),{DATA_DIR}=require('./paths'),{db}=require('./db');
const hash=x=>crypto.createHash('sha256').update(x).digest('hex').slice(0,20);
function addReference(file,key){const tag='space_asset_'+hash(key),old=db.prepare('SELECT tag FROM ref_images WHERE tag=?').get(tag);if(old)return tag;const filename='ref_'+hash(key)+path.extname(file),target=path.join(DATA_DIR,'uploads',filename);fs.mkdirSync(path.dirname(target),{recursive:true});fs.copyFileSync(file,target);db.prepare("INSERT INTO ref_images(id,tag,filename,filepath,size,mime_type,internal_only,created_at) VALUES(?,?,?,?,?,'image/png',1,datetime('now'))").run(crypto.randomUUID(),tag,filename,target,fs.statSync(target).size);return tag}
async function packGuides(key,inputs,options={}){const base=[...new Set([...(inputs.base?.refTags||[]),...(inputs.base?.anchorTags||[])])],guides=[...new Set(inputs.guide?.refTags||[])];if(!options.productStudio||new Set([...base,...guides]).size<=4||base.length>2)return packGuidesUnreserved(key,inputs);const primary=(inputs.guide?.roleRefs||[]).find(r=>r.role==='product'&&guides.includes(r.tag)&&!base.includes(r.tag));if(!primary)return packGuidesUnreserved(key,inputs);const reserved=primary.tag,rest=guides.filter(tag=>tag!==reserved),roleRefs=inputs.guide.roleRefs||[],packed=await packGuidesUnreserved(key+'-product-native-v1',{...inputs,base:{...inputs.base,refTags:[...base,reserved]},guide:{...inputs.guide,refTags:rest,roleRefs:roleRefs.filter(r=>r.tag!==reserved)}});return {...packed,base:inputs.base,guide:{...packed.guide,refTags:[reserved,...packed.guide.refTags],roleRefs:[...roleRefs.filter(r=>r.tag===reserved),...packed.guide.roleRefs],text:'Ảnh SẢN PHẨM gốc được gửi riêng ở độ phân giải gốc; không lấy thiết kế sản phẩm từ bảng mood/texture. '+(packed.guide.text||'')}}}
async function packGuidesUnreserved(key,inputs){const base=[...new Set([...(inputs.base?.refTags||[]),...(inputs.base?.anchorTags||[])])],guides=[...new Set(inputs.guide?.refTags||[])];if(new Set([...base,...guides]).size<=4)return inputs;if(base.length>3||!guides.length)throw Error('Ảnh chủ thể/mốc danh tính vượt giới hạn model. Đưa các ảnh bổ sung vào Guide để ghép bảng tham chiếu.');const file=path.join(DATA_DIR,'videos','image_guide_'+hash(key+'-hq-v2')+'.png');fs.mkdirSync(path.dirname(file),{recursive:true});if(!fs.existsSync(file)){const cols=Math.ceil(Math.sqrt(guides.length)),rows=Math.ceil(guides.length/cols),tile=Math.max(16,Math.min(1024,Math.floor(4096/Math.max(cols,rows))));let canvas=sharp({create:{width:cols*tile,height:rows*tile,channels:3,background:'#f1f1f1'}});const overlays=[];for(let i=0;i<guides.length;i++){const ref=db.prepare('SELECT filepath FROM ref_images WHERE tag=?').get(guides[i]);if(!ref||!fs.existsSync(ref.filepath))throw Error('Không tìm thấy ảnh Guide @'+guides[i]);const thumb=await sharp(ref.filepath,{limitInputPixels:50000000}).rotate().resize(tile,tile,{fit:'contain',background:'#f1f1f1'}).png().toBuffer();overlays.push({input:thumb,left:i%cols*tile,top:Math.floor(i/cols)*tile})}await canvas.composite(overlays).png().toFile(file)}const tag=addReference(file,key);const roleLabels={...require('./combinedEditSpec.cjs').REF_ROLES,...require('./videoProductionV2.cjs').VIDEO_ROLES};const roleMap=guides.map((tag,i)=>'Ô '+(i+1)+': '+(inputs.guide?.roleRefs||[]).filter(r=>r.tag===tag).map(r=>roleLabels[r.role]).filter(Boolean).join(' + ')).join('; ');return {...inputs,guide:{...inputs.guide,refTags:[tag],roleRefs:guides.flatMap((sourceTag,i)=>(inputs.guide?.roleRefs||[]).filter(r=>r.tag===sourceTag).map(r=>({...r,tag,cell:i+1}))),text:`${(inputs.guide?.roleRefs||[]).some(r=>roleLabels[r.role])?'Vai trò các ô: '+roleMap+'. ':''}Ảnh hướng dẫn @${tag} là bảng ${guides.length} ảnh, đọc từng ô theo hàng từ trái sang phải. Tất cả ảnh Guide đều có trong bảng; dùng chúng làm ngữ cảnh chung, ưu tiên yêu cầu bằng văn bản khi các ảnh có khác biệt. Không tạo lưới trong ảnh kết quả trừ khi yêu cầu storyboard.`}}}
async function splitStoryboard(key,inputs,node){const base=inputs.base;if(base?.mediaType!=='image')throw Error('Tách khung cần ảnh storyboard');const file=require('./spaceMedia').managed(base.url),rows=(node.data.autoGrid!==false?base.rowsCount:null)??node.data.rowsCount??2,cols=(node.data.autoGrid!==false?base.columns:null)??node.data.columns??3;if(!Number.isInteger(rows)||!Number.isInteger(cols)||rows<1||cols<1||rows>8||cols>8)throw Error('Lưới hỗ trợ từ 1 đến 8 hàng/cột');const normalized=await sharp(file,{limitInputPixels:50000000}).rotate().png().toBuffer({resolveWithObject:true}),{width,height}=normalized.info;if(width<cols*16||height<rows*16)throw Error('Ảnh quá nhỏ để tách theo lưới này');const items=[];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const left=Math.floor(x*width/cols),top=Math.floor(y*height/rows),w=Math.floor((x+1)*width/cols)-left,h=Math.floor((y+1)*height/rows)-top,name='image_story_'+hash(key+':'+items.length)+'.png',target=path.join(DATA_DIR,'videos',name);await sharp(normalized.data).extract({left,top,width:w,height:h}).png().toFile(target);const tag=addReference(target,key+':'+items.length);items.push({url:'/videos/'+name,mediaType:'image',width:w,height:h,refTags:[tag],anchorTags:base.anchorTags||base.refTags,label:'Khung '+(items.length+1)})}return {mediaType:'image',url:items[0].url,items,refTags:items.flatMap(x=>x.refTags),textSummary:items.length+' khung storyboard'}}
async function resolveEditRatio(data,inputs){if(data.ratioMode==='manual')return data.ratio||'3:4';let file;if(data.ratioMode==='master')file=require('./spaceMedia').managed(inputs.base?.url);else{const roles=inputs.guide?.roleRefs||[],wanted=data.ratioMode?.startsWith('role:')?data.ratioMode.slice(5):['pose','background','style','outfit','color'].find(role=>roles.some(r=>r.role===role)),ref=roles.find(r=>r.role===wanted);if(data.ratioMode?.startsWith('role:')&&!ref)throw Error('Không có ref đang dùng cho Auto ratio đã chọn');if(ref){const row=db.prepare('SELECT filepath FROM ref_images WHERE tag=?').get(ref.tag);if(!row||!fs.existsSync(row.filepath))throw Error('Ref Auto ratio không còn trên máy');file=row.filepath}else file=require('./spaceMedia').managed(inputs.base?.url)}const m=await sharp(file,{limitInputPixels:50000000}).metadata(),rotated=[5,6,7,8].includes(m.orientation);return require('./cloneBatch.cjs').nearestRatio(rotated?m.height:m.width,rotated?m.width:m.height)}
function imageList(node,inputs){const selected=(node.data.refTags||[]).map(tag=>{const r=db.prepare('SELECT tag,filename FROM ref_images WHERE tag=?').get(tag);if(!r)throw Error('Ảnh đã mất: @'+tag);return {url:'/uploads/'+r.filename,mediaType:'image',refTags:[r.tag],label:r.tag}}),incoming=Object.values(inputs).flatMap(x=>x.items||[x]).filter(x=>x?.mediaType==='image'),items=[...selected,...incoming];if(!items.length)throw Error('List ảnh đang trống');return {mediaType:'image',url:items[0].url,items,refTags:[...new Set(items.flatMap(x=>x.refTags||[]))]}}
function validSnapshot(out){try{if(!out||!['text','image','video'].includes(out.mediaType))return false;if(out.mediaType==='text')return typeof out.text==='string';for(const item of out.items||[out])require('./spaceMedia').managed(item.url);for(const tag of out.refTags||[]){const r=db.prepare('SELECT filepath FROM ref_images WHERE tag=?').get(tag);if(!r||!fs.existsSync(r.filepath))return false}return true}catch{return false}}
function crc32(buf){let c=0xffffffff;for(const byte of buf){c^=byte;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0}
function zipStore(entries){const chunks=[],central=[];let offset=0;for(const [name,buf]of entries){const n=Buffer.from(name),crc=crc32(buf),h=Buffer.alloc(30);h.writeUInt32LE(0x04034b50);h.writeUInt16LE(20,4);h.writeUInt32LE(crc,14);h.writeUInt32LE(buf.length,18);h.writeUInt32LE(buf.length,22);h.writeUInt16LE(n.length,26);chunks.push(h,n,buf);const c=Buffer.alloc(46);c.writeUInt32LE(0x02014b50);c.writeUInt16LE(20,4);c.writeUInt16LE(20,6);c.writeUInt32LE(crc,16);c.writeUInt32LE(buf.length,20);c.writeUInt32LE(buf.length,24);c.writeUInt16LE(n.length,28);c.writeUInt32LE(offset,42);central.push(c,n);offset+=h.length+n.length+buf.length}const directory=Buffer.concat(central),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(entries.length,8);end.writeUInt16LE(entries.length,10);end.writeUInt32LE(directory.length,12);end.writeUInt32LE(offset,16);return Buffer.concat([...chunks,directory,end])}
async function exportItems(key,items,format='png',single=false){if(!Array.isArray(items)||!items.length)throw Error('Không có kết quả để xuất');const entries=[];for(let i=0;i<items.length;i++){const item=items[i],name=String(i+1).padStart(3,'0');if(item.mediaType==='text'){entries.push([name+'.txt',Buffer.from(item.text||'')]);continue}const source=require('./spaceMedia').managed(item.url);if(item.mediaType==='image'){const pipeline=sharp(source,{limitInputPixels:50000000}).rotate();entries.push([name+(format==='jpg'?'.jpg':'.png'),await (format==='jpg'?pipeline.flatten({background:'#fff'}).jpeg({quality:95}):pipeline.png()).toBuffer()])}else entries.push([name+path.extname(source),fs.readFileSync(source)])}const dir=path.join(DATA_DIR,'space-exports');fs.mkdirSync(dir,{recursive:true});const name='export_'+hash(key)+(single&&entries.length===1?path.extname(entries[0][0]):'.zip');fs.writeFileSync(path.join(dir,name),single&&entries.length===1?entries[0][1]:zipStore(entries));return {downloadUrl:'/api/spaces/components/export/'+name,count:items.length}}
